
import os
import csv
import shutil
import xml.etree.ElementTree as ET
from collections import Counter

# ============================================================
# 1. CONFIGURATION
# ============================================================

# Original RDD2022 dataset
SOURCE_DATASET = (
    r"C:\Users\mitran\Downloads\InfraScan-DataSet"
    r"\New folder\RDD2022"
)

# Cleaned annotations generated by annotation_cleaner.py
CLEANED_DATASET = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    "processed_dataset"
)

COUNTRIES = [
    "China_Drone",
    "China_MotorBike",
    "United_States",
    "Czech",
    "Japan",
    "Norway",
    "India"
]

REPORT_DIR = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    "reports"
)

os.makedirs(REPORT_DIR, exist_ok=True)

# ============================================================
# 2. GLOBAL STATISTICS
# ============================================================

total_annotations = 0
total_images_copied = 0
total_objects = 0
total_negative_images = 0
missing_images = 0
missing_annotations = 0
invalid_xml_files = 0

manifest = []
preparation_issues = []
country_summary = []

# ============================================================
# 3. HELPER FUNCTION: SAVE CSV
# ============================================================

def save_csv(filename, headers, rows):

    filepath = os.path.join(REPORT_DIR, filename)

    with open(
        filepath,
        "w",
        newline="",
        encoding="utf-8-sig"
    ) as file:

        writer = csv.DictWriter(
            file,
            fieldnames=headers
        )

        writer.writeheader()
        writer.writerows(rows)

    print(f"Report saved: {filepath}")


# ============================================================
# 4. VALIDATE SOURCE PATH
# ============================================================

if not os.path.isdir(SOURCE_DATASET):
    raise FileNotFoundError(
        f"Original dataset not found: {SOURCE_DATASET}"
    )

if not os.path.isdir(CLEANED_DATASET):
    raise FileNotFoundError(
        f"Cleaned annotations not found: {CLEANED_DATASET}"
    )

print("\n========== DATASET PREPARATION ==========\n")


# ============================================================
# 5. PROCESS EACH COUNTRY
# ============================================================

for country in COUNTRIES:

    print(f"\nProcessing: {country}")
    print("-" * 45)

    source_image_dir = os.path.join(
        SOURCE_DATASET,
        country,
        "train",
        "images"
    )

    source_xml_dir = os.path.join(
        SOURCE_DATASET,
        country,
        "train",
        "annotations",
        "xmls"
    )

    cleaned_xml_dir = os.path.join(
        CLEANED_DATASET,
        country,
        "train",
        "annotations",
        "xmls"
    )

    output_image_dir = os.path.join(
        CLEANED_DATASET,
        country,
        "train",
        "images"
    )

    if not os.path.isdir(source_image_dir):
        print("Source image directory missing.")
        preparation_issues.append({
            "country": country,
            "filename": "",
            "issue": "Source image directory missing"
        })
        continue

    if not os.path.isdir(cleaned_xml_dir):
        print("Cleaned annotation directory missing.")
        preparation_issues.append({
            "country": country,
            "filename": "",
            "issue": "Cleaned annotation directory missing"
        })
        continue

    os.makedirs(output_image_dir, exist_ok=True)

    source_images = set(os.listdir(source_image_dir))
    source_xml_files = set(os.listdir(source_xml_dir))

    cleaned_xml_files = [
        filename
        for filename in os.listdir(cleaned_xml_dir)
        if filename.lower().endswith(".xml")
    ]

    country_images = 0
    country_objects = 0
    country_negatives = 0
    country_missing = 0
    country_invalid = 0

    # --------------------------------------------------------
    # MATCH CLEANED ANNOTATIONS WITH ORIGINAL IMAGES
    # --------------------------------------------------------

    for xml_file in cleaned_xml_files:

        cleaned_xml_path = os.path.join(
            cleaned_xml_dir,
            xml_file
        )

        try:
            tree = ET.parse(cleaned_xml_path)
            root = tree.getroot()

            image_filename = root.findtext("filename")

            if not image_filename:
                country_invalid += 1
                invalid_xml_files += 1

                preparation_issues.append({
                    "country": country,
                    "filename": xml_file,
                    "issue": "Image filename missing from XML"
                })

                continue

            # Check the corresponding original image
            if image_filename not in source_images:

                country_missing += 1
                missing_images += 1

                preparation_issues.append({
                    "country": country,
                    "filename": image_filename,
                    "issue": "Matching source image missing"
                })

                continue

            source_image_path = os.path.join(
                source_image_dir,
                image_filename
            )

            output_image_path = os.path.join(
                output_image_dir,
                image_filename
            )

            # Copy image only if it is not already present
            if not os.path.exists(output_image_path):
                shutil.copy2(
                    source_image_path,
                    output_image_path
                )

            # Count objects in the cleaned annotation
            objects = root.findall("object")
            object_count = len(objects)

            country_images += 1
            total_images_copied += 1

            country_objects += object_count
            total_objects += object_count

            # Empty XML = candidate negative sample.
            # Its status is provisional until labels are verified.
            if object_count == 0:

                country_negatives += 1
                total_negative_images += 1

                annotation_status = "candidate_negative"

            else:
                annotation_status = "annotated"

            # Add dataset manifest record
            manifest.append({
                "country": country,
                "image_filename": image_filename,
                "annotation_filename": xml_file,
                "image_path": os.path.relpath(
                    output_image_path,
                    CLEANED_DATASET
                ),
                "annotation_path": os.path.relpath(
                    cleaned_xml_path,
                    CLEANED_DATASET
                ),
                "image_exists": True,
                "object_count": object_count,
                "annotation_status": annotation_status
            })

            total_annotations += 1

        except ET.ParseError as error:

            country_invalid += 1
            invalid_xml_files += 1

            preparation_issues.append({
                "country": country,
                "filename": xml_file,
                "issue": f"Malformed cleaned XML: {error}"
            })

    # --------------------------------------------------------
    # FIND ORIGINAL XML FILES WITHOUT CLEANED COUNTERPARTS
    # --------------------------------------------------------

    for xml_file in source_xml_files:

        if (
            xml_file.lower().endswith(".xml")
            and xml_file not in cleaned_xml_files
        ):

            missing_annotations += 1

            preparation_issues.append({
                "country": country,
                "filename": xml_file,
                "issue": "Original XML has no cleaned counterpart"
            })

    # --------------------------------------------------------
    # COUNTRY SUMMARY
    # --------------------------------------------------------

    country_summary.append({
        "country": country,
        "prepared_images": country_images,
        "prepared_annotations": country_images,
        "valid_objects": country_objects,
        "candidate_negative_images": country_negatives,
        "missing_images": country_missing,
        "invalid_xml_files": country_invalid
    })

    print(f"Prepared images:          {country_images}")
    print(f"Valid objects:            {country_objects}")
    print(f"Candidate negatives:      {country_negatives}")
    print(f"Missing images:           {country_missing}")
    print(f"Invalid XML files:        {country_invalid}")


# ============================================================
# 6. GENERATE DATASET MANIFEST
# ============================================================

save_csv(
    "dataset_manifest.csv",
    [
        "country",
        "image_filename",
        "annotation_filename",
        "image_path",
        "annotation_path",
        "image_exists",
        "object_count",
        "annotation_status"
    ],
    manifest
)


# ============================================================
# 7. GENERATE COUNTRY SUMMARY
# ============================================================

save_csv(
    "dataset_preparation_summary.csv",
    [
        "country",
        "prepared_images",
        "prepared_annotations",
        "valid_objects",
        "candidate_negative_images",
        "missing_images",
        "invalid_xml_files"
    ],
    country_summary
)


# ============================================================
# 8. GENERATE ISSUE REPORT
# ============================================================

save_csv(
    "dataset_preparation_issues.csv",
    [
        "country",
        "filename",
        "issue"
    ],
    preparation_issues
)


# ============================================================
# 9. FINAL SUMMARY
# ============================================================

print("\n========== PREPARATION SUMMARY ==========")

print(f"Prepared images:          {total_images_copied}")
print(f"Prepared annotations:     {total_annotations}")
print(f"Valid objects:            {total_objects}")
print(f"Candidate negatives:      {total_negative_images}")
print(f"Missing images:           {missing_images}")
print(f"Missing annotations:      {missing_annotations}")
print(f"Invalid XML files:        {invalid_xml_files}")

print("\n========== PREPARATION COMPLETE ==========")

print(f"Processed dataset: {CLEANED_DATASET}")
print(f"Reports directory: {REPORT_DIR}")

print("\nReview the manifest and issue report before splitting.")
